ALTER POLICY "posts readable" ON public.posts TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY "own posts read" ON public.posts FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY "active anonymous listings read" ON public.posts FOR SELECT TO authenticated USING (status='active' AND public.account_allowed(user_id) AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()));
ALTER POLICY "campaign_read" ON public.referral_vip_campaign TO authenticated USING (public.has_role(auth.uid(),'admin'));
REVOKE SELECT ON public.referral_vip_campaign FROM anon;
CREATE OR REPLACE FUNCTION public.public_referral_vip_board() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.has_role(auth.uid(),'admin') THEN jsonb_build_object('limit',10,'event_label',coalesce((SELECT event_label FROM public.referral_vip_campaign WHERE id),'నిర్వాహకుడు ప్రకటిస్తారు'),'totals',jsonb_build_object('TG',NULL,'AP',NULL),'rows',CASE WHEN now()<'2026-11-22 23:00:00+05:30'::timestamptz THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(rowdata ORDER BY place) FROM (SELECT r.rank_no place,jsonb_build_object('rank',r.rank_no,'count',r.joins,'name',c.display_name,'region',c.region,'photo_path',CASE WHEN c.photo_consent AND s.published AND s.photo_path LIKE s.user_id::text||'/%' THEN s.photo_path ELSE '' END) rowdata FROM public.referral_vip_ranks() r JOIN public.referral_board_consent c ON c.user_id=r.user_id LEFT JOIN public.service_profiles s ON s.user_id=r.user_id WHERE c.published AND c.region IN('TG','AP') AND r.rank_no<=10) a),'[]'::jsonb) END) ELSE jsonb_build_object('limit',0,'event_label','','totals',jsonb_build_object('TG',NULL,'AP',NULL),'rows','[]'::jsonb) END $$;
COMMENT ON TABLE public.referral_vip_campaign IS 'Administrator-only competition configuration; public board returns no competition details for non-admin callers.';